import{_ as a}from"./chunks/9d335e252cac10e7e6ee4a1fc4b169a8.1mYleQbu.js";import{_ as d,c as e,a2 as r,o}from"./chunks/framework.BnrAgU0Y.js";const g=JSON.parse('{"title":"Langflow 中的数据组件","description":"Langflow 中的数据组件","frontmatter":{"title":"Langflow 中的数据组件","description":"Langflow 中的数据组件","layout":"doc"},"headers":[],"relativePath":"langflow/components-data.md","filePath":"langflow/components-data.md"}'),s={name:"langflow/components-data.md"};function h(n,t,i,l,u,p){return o(),e("div",null,t[0]||(t[0]=[r('<h1 id="langflow-中的数据组件" tabindex="-1">Langflow 中的数据组件 <a class="header-anchor" href="#langflow-中的数据组件" aria-label="Permalink to &quot;Langflow 中的数据组件&quot;">​</a></h1><p>数据组件用于将数据从来源加载到您的流程中。</p><p>它们可能会执行一些处理或类型检查，例如将原始 HTML 数据转换为文本，或者确保您加载的文件类型是可接受的。</p><h2 id="在流程中使用数据组件" tabindex="-1">在流程中使用数据组件 <a class="header-anchor" href="#在流程中使用数据组件" aria-label="Permalink to &quot;在流程中使用数据组件&quot;">​</a></h2><p><strong>URL</strong> 数据组件从一组 URL 中加载内容。</p><p>在组件的 <strong>URLs</strong> 字段中，输入用逗号分隔的 URL 列表，你想加载的内容。或者，连接一个输出 <code>Message</code> 类型的组件，例如 <strong>Chat Input</strong>（聊天输入）组件，来通过组件提供你的 URL。</p><p>要输出 <code>Data</code> 类型，在 <strong>Output Format</strong>（输出格式）下拉菜单中，选择 <strong>Raw HTML</strong>（原始 HTML）。要输出 <code>Message</code> 类型，在 <strong>Output Format</strong>（输出格式）下拉菜单中，选择 <strong>Text</strong>（文本）。此选项会通过 <code>data_to_text</code> 辅助函数应用后处理。</p><p>在文档摄取管道的这个示例中，URL 组件将原始 HTML 输出到文本分割器，该分割器将原始内容分割成块，以供向量数据库摄取。</p><p><img src="'+a+`" alt="URL component in a data ingestion pipeline"></p><h2 id="api-请求" tabindex="-1">API 请求 <a class="header-anchor" href="#api-请求" aria-label="Permalink to &quot;API 请求&quot;">​</a></h2><p>该组件使用 URL 或 cURL 命令发起 HTTP 请求。</p><h3 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>urls</td><td>URLs</td><td>输入一个或多个URL，用逗号分隔。</td></tr><tr><td>curl</td><td>cURL</td><td>粘贴curl命令以填充字典字段的headers和body。</td></tr><tr><td>method</td><td>Method</td><td>要使用的HTTP方法。</td></tr><tr><td>use_curl</td><td>Use cURL</td><td>启用cURL模式以从cURL命令填充字段。</td></tr><tr><td>query_params</td><td>Query Parameters</td><td>要附加到URL的查询参数。</td></tr><tr><td>body</td><td>Body</td><td>随请求一起发送的主体，作为字典形式（用于 <code>POST</code>、<code>PATCH</code>、<code>PUT</code>）。</td></tr><tr><td>headers</td><td>Headers</td><td>要随请求发送的头信息，作为字典形式。</td></tr><tr><td>timeout</td><td>Timeout</td><td>要用于请求的超时时间。</td></tr><tr><td>follow_redirects</td><td>Follow Redirects</td><td>是否跟随HTTP重定向。</td></tr><tr><td>save_to_file</td><td>Save to File</td><td>将API响应保存到临时文件。</td></tr><tr><td>include_httpx_metadata</td><td>Include HTTPx Metadata</td><td>在输出中包含诸如 <code>headers</code>、<code>status_code</code>、<code>response_headers</code> 以及 <code>redirection_history</code> 的属性。</td></tr></tbody></table><h3 id="api-outputs" tabindex="-1">输出 <a class="header-anchor" href="#api-outputs" aria-label="Permalink to &quot;输出 {#api-outputs}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>data</td><td>Data</td><td>API 请求的结果。</td></tr></tbody></table><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><p>该组件递归地从目录中加载文件，并可选择设置文件类型、深度和并发性。</p><h3 id="inputs-1" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-1" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>输入</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>path</td><td>MessageTextInput</td><td>加载文件的目录路径</td></tr><tr><td>types</td><td>MessageTextInput</td><td>要加载的文件类型（留空以加载所有类型）</td></tr><tr><td>depth</td><td>IntInput</td><td>搜索文件的深度</td></tr><tr><td>max_concurrency</td><td>IntInput</td><td>加载文件的最大并发数</td></tr><tr><td>load_hidden</td><td>BoolInput</td><td>如果为 true，加载隐藏文件</td></tr><tr><td>recursive</td><td>BoolInput</td><td>如果为 true，则递归搜索</td></tr><tr><td>silent_errors</td><td>BoolInput</td><td>如果为 true，错误不会触发异常</td></tr><tr><td>use_multithreading</td><td>BoolInput</td><td>如果为 true，使用多线程</td></tr></tbody></table><h3 id="directory-outputs" tabindex="-1">Outputs <a class="header-anchor" href="#directory-outputs" aria-label="Permalink to &quot;Outputs {#directory-outputs}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Output</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>data</td><td>List[Data]</td><td>从目录加载的文件数据</td></tr></tbody></table><h2 id="file" tabindex="-1">File <a class="header-anchor" href="#file" aria-label="Permalink to &quot;File&quot;">​</a></h2><p><code>FileComponent</code> 是一个类，用于加载和解析多种支持格式的文本文件，将内容转换为一个Data对象。它支持多种文件类型，并提供静默错误处理选项。</p><p>支持的最大文件大小为100 MB。</p><h3 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>path</td><td>Path</td><td>要加载的文件路径。</td></tr><tr><td>silent_errors</td><td>Silent Errors</td><td>如果为 true，则错误不抛出异常。</td></tr></tbody></table><h3 id="file-outputs" tabindex="-1">输出 <a class="header-anchor" href="#file-outputs" aria-label="Permalink to &quot;输出 {#file-outputs}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>data</td><td>Data</td><td>作为Data对象解析的文件内容。</td></tr></tbody></table><h2 id="gmail-loader" tabindex="-1">Gmail Loader <a class="header-anchor" href="#gmail-loader" aria-label="Permalink to &quot;Gmail Loader&quot;">​</a></h2><p>该组件使用提供的凭证和过滤器从 Gmail 加载电子邮件。</p><p>关于如何创建服务帐户 JSON 的更多信息，请参见 <a href="https://developers.google.com/identity/protocols/oauth2/service-account" target="_blank" rel="noreferrer">服务帐户 JSON</a>。</p><h3 id="inputs-2" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-2" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>输入项</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>json_string</td><td>SecretStrInput</td><td>包含服务账户访问的 OAuth 2.0 访问令牌信息的 JSON 字符串</td></tr><tr><td>label_ids</td><td>MessageTextInput</td><td>过滤电子邮件的标签 ID 列表，使用逗号分隔</td></tr><tr><td>max_results</td><td>MessageTextInput</td><td>加载电子邮件的最大数量</td></tr></tbody></table><h3 id="gmail-outputs" tabindex="-1">Outputs <a class="header-anchor" href="#gmail-outputs" aria-label="Permalink to &quot;Outputs {#gmail-outputs}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Output</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>data</td><td>Data</td><td>加载的电子邮件数据</td></tr></tbody></table><h2 id="google-drive-loader" tabindex="-1">Google Drive Loader <a class="header-anchor" href="#google-drive-loader" aria-label="Permalink to &quot;Google Drive Loader&quot;">​</a></h2><p>该组件使用提供的凭据和单一文档ID从Google Drive加载文档。</p><p>有关创建服务账号JSON的更多信息，请参阅<a href="https://developers.google.com/identity/protocols/oauth2/service-account" target="_blank" rel="noreferrer">服务账号JSON</a>。</p><h3 id="inputs-3" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-3" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>输入</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>json_string</td><td>SecretStrInput</td><td>包含用于服务账户访问的 OAuth 2.0 访问令牌信息的 JSON 字符串</td></tr><tr><td>document_id</td><td>MessageTextInput</td><td>单个 Google Drive 文档 ID</td></tr></tbody></table><h3 id="gdrive-outputs" tabindex="-1">Outputs <a class="header-anchor" href="#gdrive-outputs" aria-label="Permalink to &quot;Outputs {#gdrive-outputs}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Output</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>docs</td><td>Data</td><td>已加载的文档数据</td></tr></tbody></table><h2 id="google-drive-搜索" tabindex="-1">Google Drive 搜索 <a class="header-anchor" href="#google-drive-搜索" aria-label="Permalink to &quot;Google Drive 搜索&quot;">​</a></h2><p>这个组件使用提供的凭据和查询参数搜索 Google Drive 文件。</p><p>有关创建服务帐号 JSON 的更多信息，请参见<a href="https://developers.google.com/identity/protocols/oauth2/service-account" target="_blank" rel="noreferrer">服务帐号 JSON</a>。</p><h3 id="inputs-4" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-4" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>输入项</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>token_string</td><td>SecretStrInput</td><td>包含用于服务账户访问的 OAuth 2.0 访问令牌信息的 JSON 字符串</td></tr><tr><td>query_item</td><td>DropdownInput</td><td>要查询的字段</td></tr><tr><td>valid_operator</td><td>DropdownInput</td><td>查询中使用的运算符</td></tr><tr><td>search_term</td><td>MessageTextInput</td><td>在指定查询项中要搜索的值</td></tr><tr><td>query_string</td><td>MessageTextInput</td><td>用于搜索的查询字符串（可以手动编辑）</td></tr></tbody></table><h3 id="gdrive-search-outputs" tabindex="-1">Outputs <a class="header-anchor" href="#gdrive-search-outputs" aria-label="Permalink to &quot;Outputs {#gdrive-search-outputs}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>输出项</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>doc_urls</td><td>List[str]</td><td>所找到文档的URLs</td></tr><tr><td>doc_ids</td><td>List[str]</td><td>所找到文档的IDs</td></tr><tr><td>doc_titles</td><td>List[str]</td><td>所找到文档的标题</td></tr><tr><td>Data</td><td>Data</td><td>以结构化格式的文档标题和URLs</td></tr></tbody></table><h2 id="sql-查询" tabindex="-1">SQL 查询 <a class="header-anchor" href="#sql-查询" aria-label="Permalink to &quot;SQL 查询&quot;">​</a></h2><p>该组件在指定的数据库上执行 SQL 查询。</p><h3 id="inputs-5" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-5" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>query</td><td>Query</td><td>要执行的 SQL 查询。</td></tr><tr><td>database_url</td><td>Database URL</td><td>数据库的 URL。</td></tr><tr><td>include_columns</td><td>Include Columns</td><td>在结果中包含列。</td></tr><tr><td>passthrough</td><td>Passthrough</td><td>如果发生错误，返回查询而不是抛出异常。</td></tr><tr><td>add_error</td><td>Add Error</td><td>将错误添加到结果中。</td></tr></tbody></table><h3 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>result</td><td>Result</td><td>SQL查询执行的结果。</td></tr></tbody></table><h2 id="url" tabindex="-1">URL <a class="header-anchor" href="#url" aria-label="Permalink to &quot;URL&quot;">​</a></h2><p>该组件从一个或多个 URL 获取内容，处理内容后返回为<a href="/concepts-objects">数据</a>对象的列表。</p><h3 id="inputs-6" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-6" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>urls</td><td>URLs</td><td>输入一个或多个URL（网址）</td></tr></tbody></table><h3 id="outputs-1" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-1" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>data</td><td>Data</td><td>包含获取的内容和元数据的数据对象列表</td></tr></tbody></table><h2 id="webhook" tabindex="-1">Webhook <a class="header-anchor" href="#webhook" aria-label="Permalink to &quot;Webhook&quot;">​</a></h2><p>该组件定义了一个 webhook 触发器，当接收到 HTTP POST 请求时，会运行一个流程。</p><p>如果输入不是有效的 JSON，对象就会被包裹在一个 <code>payload</code> 对象中，便于处理并仍然触发流程。该组件不需要 API 密钥。</p><p>当在工作区添加一个 <strong>Webhook</strong> 组件时，<strong>API</strong> 面板中会出现一个新的 <strong>Webhook cURL</strong> 选项卡，其中包含用于触发 webhook 组件的 HTTP POST 请求。例如：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;http://127.0.0.1:7860/api/v1/webhook/**YOUR_FLOW_ID**&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;any&quot;: &quot;data&quot;}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>测试 webhook 组件的方法：</p><ol><li>添加一个 <strong>Webhook</strong> 组件到流程中。</li><li>将 <strong>Webhook</strong> 组件的 <strong>Data</strong> 输出连接到 <a href="./URL.html"><strong>Data to Message</strong></a> 组件的 <strong>Data</strong> 输入。</li><li>将 <strong>Data to Message</strong> 组件的 <strong>Message</strong> 输出连接到 <a href="./URL.html"><strong>Chat Output</strong></a> 组件的 <strong>Text</strong> 输入。</li><li>在 <strong>API</strong> 面板中的 <strong>Webhook cURL</strong> 选项卡中复制代码，然后粘贴到终端。</li><li>发送 POST 请求。</li><li>打开 <strong>Playground</strong>。 你的 JSON 数据将被发送到 <strong>Chat Output</strong> 组件，这表明 webhook 组件已正确触发流程。</li></ol><h3 id="inputs-7" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-7" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>data</td><td>String</td><td>用于测试 webhook 组件的 JSON 负载</td></tr></tbody></table><h3 id="outputs-2" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-2" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>output_data</td><td>Data 数据</td><td>从 webhook 输入中处理的数据信息</td></tr></tbody></table>`,72)]))}const m=d(s,[["render",h]]);export{g as __pageData,m as default};
